style.css:
/* Merlot Hour - aesthetic wine red theme (all sites) */
/* i really want this to be global */

/* colors: swap these values to remix */
:root {
  --my-wine-light: #5a1224;  /* top of the gradient */
  --my-wine-dark: #280511;   /* bottom of the gradient */
  --my-text: #f4e4dc;        /* warm cream text */
  --my-link: #f0a99b;        /* rose gold links */
  --my-hover: #ffd9cf;       /* link hover */
  --my-accent: #8f2a44;      /* selection and scrollbar */
}

/* wine gradient background */
html, body {
  background-color: var(--my-wine-dark) !important;
  background-image: linear-gradient(160deg, var(--my-wine-light), var(--my-wine-dark)) !important;
  background-attachment: fixed !important;
  color: var(--my-text) !important;
  color-scheme: dark !important;
}

/* rose gold links */
a:link, a:visited {
  color: var(--my-link) !important;
  text-decoration-color: var(--my-accent) !important;
  text-underline-offset: 3px !important;
}
a:hover {
  color: var(--my-hover) !important;
}

/* elegant serif headings */
h1, h2, h3, h4, h5, h6 {
  font-family: Georgia, "Palatino Linotype", "Book Antiqua", serif !important;
  color: var(--my-text) !important;
  letter-spacing: 0.02em !important;
}

/* rounded corners */
img, video, button, input, textarea, select {
  border-radius: 12px !important;
}

/* wine-toned form fields */
input, textarea, select {
  background-color: rgba(255, 255, 255, 0.08) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-accent) !important;
  caret-color: var(--my-link) !important;
}

/* text selection */
::selection {
  background: var(--my-accent) !important;
  color: var(--my-hover) !important;
}

/* wine scrollbar */
html {
  scrollbar-color: var(--my-accent) var(--my-wine-dark) !important;
}
